"""Random input generator + differential test against the reference."""
import json
import random
import subprocess
import sys
import math
import pathlib
from fractions import Fraction

sys.path.insert(0, str(pathlib.Path(__file__).resolve().parent))
import ref

INV = (2, 1, 0)


def scopes_of(core_list, final):
    occ = ref.occurrences(final, core_list)
    m = len(core_list)
    out = []
    for e in range(m):
        ctx = set()
        for (c, lk, rk) in occ[e]:
            if lk[0] == 'v':
                ctx.add(lk[1])
            if rk[0] == 'v':
                ctx.add(rk[1])
        out.append(tuple(sorted(ctx | {e})))
    return out


def find_order(core_list, final, rng, tries=200):
    """Return an elimination order of width <= 4 or None."""
    m = len(core_list)
    if m == 0:
        return []
    scopes = scopes_of(core_list, final)
    best = None
    for _ in range(tries):
        adj = [set() for _ in range(m)]
        for s in scopes:
            for i in range(len(s)):
                for j in range(i + 1, len(s)):
                    adj[s[i]].add(s[j])
                    adj[s[j]].add(s[i])
        alive = set(range(m))
        order = []
        width = 0
        ok = True
        while alive:
            cands = sorted(alive, key=lambda v: (len(adj[v] & alive), rng.random()))
            # pick among the smallest few at random
            k = min(len(cands), 1 + rng.randrange(3))
            pick = cands[0] if rng.random() < 0.7 else rng.choice(cands[:k])
            nbrs = adj[pick] & alive
            width = max(width, len(nbrs))
            if width > 4:
                ok = False
                break
            nl = list(nbrs)
            for i in range(len(nl)):
                for j in range(i + 1, len(nl)):
                    adj[nl[i]].add(nl[j])
                    adj[nl[j]].add(nl[i])
            order.append(pick)
            alive.discard(pick)
        if ok:
            best = [core_list[v] for v in order]
            return best
    return None


def gen(rng):
    pool = rng.sample(range(1, 400), rng.randint(3, 9))
    ixps = set(rng.sample(pool, rng.randint(0, min(2, len(pool)))))
    rib = []
    for _ in range(rng.randint(1, 8)):
        n = rng.randint(1, 6)
        path = [rng.choice(pool)]
        for _ in range(n):
            nxt = rng.choice(pool)
            while nxt == path[-1]:
                nxt = rng.choice(pool)
            path.append(nxt)
        # inject ixps and prepending
        out = []
        for a in path:
            if rng.random() < 0.25:
                out.append(a)
            if ixps and rng.random() < 0.3:
                out.append(rng.choice(sorted(ixps)))
        if rng.random() < 0.2:
            out.append(rng.choice(pool))
        rib.append({'path': out, 'count': rng.randint(1, 6)})
    priors = []
    seen = set()
    for _ in range(rng.randint(0, 3)):
        u, v = rng.sample(pool, 2)
        if canon_pair(u, v) in seen:
            continue
        seen.add(canon_pair(u, v))
        w = [rng.randint(0, 4) for _ in range(3)]
        if sum(w) == 0:
            w[rng.randrange(3)] = 1
        priors.append({'link': [u, v], 'weights': w})
    declared = []
    for _ in range(rng.randint(0, 2)):
        u, v = rng.sample(pool, 2)
        if canon_pair(u, v) in seen:
            continue
        seen.add(canon_pair(u, v))
        declared.append({'link': [u, v],
                         'rel': rng.choice(['c2p', 'p2p', 'p2c'])})
    queries = []
    allpool = pool + [x + 1000 for x in pool]
    for k in range(rng.randint(0, 6)):
        n = rng.randint(0, 6)
        path = [rng.choice(allpool) for _ in range(n)]
        if path and rng.random() < 0.25:
            path.append(path[0])  # loop
        a = rng.randint(0, 10)
        b = rng.randint(max(1, a), 10)
        queries.append({'id': 'q%d' % k, 'path': path, 'threshold': [a, b]})
    # compute a valid order
    agg = ref.aggregate([(tuple(r['path']), r['count']) for r in rib], ixps)
    _links, _rounds, final = ref.peel_naive(agg)
    core = set()
    for p in final:
        for i in range(len(p) - 1):
            core.add(ref.canon(p[i], p[i + 1]))
    order = find_order(sorted(core), final, rng)
    if order is None:
        return None
    return {'version': 1, 'ixps': sorted(ixps), 'rib': rib, 'priors': priors,
            'declared': declared, 'order': order, 'queries': queries}


def canon_pair(u, v):
    return (u, v) if u < v else (v, u)


def equal(expected, actual, path=''):
    if isinstance(expected, dict):
        if not isinstance(actual, dict) or set(expected) != set(actual):
            return 'key mismatch at %s: %r vs %r' % (path, expected, actual)
        for k, v in expected.items():
            r = equal(v, actual[k], path + '/' + str(k))
            if r:
                return r
        return None
    if isinstance(expected, list):
        if not isinstance(actual, list) or len(expected) != len(actual):
            return 'list mismatch at %s' % path
        for i, (x, y) in enumerate(zip(expected, actual)):
            r = equal(x, y, path + '[%d]' % i)
            if r:
                return r
        return None
    if isinstance(expected, float):
        if isinstance(actual, bool) or not isinstance(actual, (int, float)):
            return 'type mismatch at %s: %r vs %r' % (path, expected, actual)
        if not math.isfinite(actual) or abs(expected - actual) > 1e-8:
            return 'value mismatch at %s: %r vs %r' % (path, expected, actual)
        return None
    if type(expected) is not type(actual) or expected != actual:
        return 'mismatch at %s: %r vs %r' % (path, expected, actual)
    return None


def main():
    seed = int(sys.argv[1]) if len(sys.argv) > 1 else 0
    count = int(sys.argv[2]) if len(sys.argv) > 2 else 200
    rng = random.Random(seed)
    zero = 0
    for i in range(count):
        doc = None
        while doc is None:
            doc = gen(rng)
        expected = ref.reference(doc)
        raw = json.dumps(doc).encode()
        out = subprocess.run([sys.executable, '-I', 'submission/main.py'],
                             input=raw, stdout=subprocess.PIPE, cwd='.')
        try:
            actual = json.loads(out.stdout.decode())
        except Exception:
            print('BAD OUTPUT', out.stdout[:200], out.stderr[:500])
            print(json.dumps(doc))
            return 1
        msg = equal(expected, actual)
        if msg or out.returncode != 0:
            print('FAIL seed=%d iter=%d rc=%d: %s' % (seed, i, out.returncode, msg))
            print(json.dumps(doc))
            print('expected', json.dumps(expected))
            print('actual  ', json.dumps(actual))
            return 1
        if expected.get('error') == 'zero-partition':
            zero += 1
    print('OK %d cases (%d zero-partition)' % (count, zero))
    return 0


if __name__ == '__main__':
    raise SystemExit(main())
